SELECT jsonb_build_object(
 'posts',(SELECT jsonb_build_object('audit',jsonb_build_object('pending',count(*) FILTER(WHERE visibility<>'deleted' AND audit_status='pending'),'approved',count(*) FILTER(WHERE visibility<>'deleted' AND audit_status='approved'),'rejected',count(*) FILTER(WHERE visibility<>'deleted' AND audit_status='rejected')),'visibility',jsonb_build_object('visible',count(*) FILTER(WHERE visibility='visible'),'hidden',count(*) FILTER(WHERE visibility='hidden'),'offline',count(*) FILTER(WHERE visibility='offline'),'deleted',count(*) FILTER(WHERE visibility='deleted')),'public',count(*) FILTER(WHERE audit_status='approved' AND visibility='visible' AND EXISTS(SELECT 1 FROM schools WHERE id=p.school_id AND active))) FROM posts p WHERE school_id=ANY($1) AND created_at>=$2 AND created_at<$3),
 'comments',(SELECT jsonb_build_object('audit',jsonb_build_object('pending',count(*) FILTER(WHERE NOT deleted AND audit_status='pending'),'approved',count(*) FILTER(WHERE NOT deleted AND audit_status='approved'),'rejected',count(*) FILTER(WHERE NOT deleted AND audit_status='rejected')),'visibility',jsonb_build_object('visible',count(*) FILTER(WHERE NOT deleted AND visibility='visible'),'hidden',count(*) FILTER(WHERE NOT deleted AND visibility='hidden'),'deleted',count(*) FILTER(WHERE deleted)),'public',count(*) FILTER(WHERE NOT deleted AND audit_status='approved' AND visibility='visible' AND EXISTS(SELECT 1 FROM posts p JOIN schools s ON s.id=p.school_id WHERE p.id=c.post_id AND p.audit_status='approved' AND p.visibility='visible' AND s.active))) FROM comments c WHERE school_id=ANY($1) AND created_at>=$2 AND created_at<$3))
